const name = $json.Name;
const studentId = $json.YourID;


const now = new Date();


const egyptTime = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Africa/Cairo',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false,
}).format(now);


const egyptDate = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Africa/Cairo',
}).format(now);


const [hours, minutes, seconds] = egyptTime.split(':').map(Number);

const currentSeconds =
  hours * 3600 +
  minutes * 60 +
  seconds;

const startSeconds = 3 * 3600  ;       
const endSeconds = 3* 3600 + 40 * 60; 

const status =
  currentSeconds >= startSeconds &&
  currentSeconds <= endSeconds
    ? 'Present'
    : 'Absent';

return {
  Date: egyptDate,
  Student_ID: studentId,
  Name: name,
  Time: egyptTime,
  Status: status,
};

// Get AI Agent output
const raw = $json.output;

// Parse JSON returned by the AI Agent
let report;

try {
  report = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) {
  throw new Error('AI Agent output is not valid JSON');
}

const {
  date,
  total_active_students,
  present,
  absent,
  online,
  offline,
  warnings_sent,
  dismissals_sent,
  absent_students = []
} = report;

// Escape HTML to prevent malformed output
function escapeHTML(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

// Generate absent students rows
const absentRows = absent_students.length
  ? absent_students.map(student => `
      <tr>
        <td>${escapeHTML(student.student_id)}</td>
        <td>${escapeHTML(student.name)}</td>
        <td>${escapeHTML(student.previous_absence_count)}</td>
        <td>${escapeHTML(student.updated_absence_count)}</td>
        <td>${escapeHTML(student.status)}</td>
        <td>${escapeHTML(student.action)}</td>
      </tr>
    `).join('')
  : `
      <tr>
        <td colspan="6" class="no-data">
          No students were absent today.
        </td>
      </tr>
    `;

// HTML
const html = `
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Daily Attendance Report</title>
</head>

<body>

  <div class="header">
    <h1>Daily Attendance Report</h1>
    <p>Date: ${escapeHTML(date)}</p>
  </div>

  <div class="summary-grid">

    <div class="card">
      <span class="label">Total Students</span>
      <span class="value">${escapeHTML(total_active_students)}</span>
    </div>

    <div class="card present">
      <span class="label">Present</span>
      <span class="value">${escapeHTML(present)}</span>
    </div>

    <div class="card absent">
      <span class="label">Absent</span>
      <span class="value">${escapeHTML(absent)}</span>
    </div>

    <div class="card">
      <span class="label">Online</span>
      <span class="value">${escapeHTML(online)}</span>
    </div>

    <div class="card">
      <span class="label">Offline</span>
      <span class="value">${escapeHTML(offline)}</span>
    </div>

    <div class="card warning">
      <span class="label">Warnings Sent</span>
      <span class="value">${escapeHTML(warnings_sent)}</span>
    </div>

    <div class="card dismissal">
      <span class="label">Dismissals</span>
      <span class="value">${escapeHTML(dismissals_sent)}</span>
    </div>

  </div>

  <div class="section">
    <h2>Absent Students</h2>

    <table>
      <thead>
        <tr>
          <th>Student ID</th>
          <th>Name</th>
          <th>Previous Absences</th>
          <th>Updated Absences</th>
          <th>Status</th>
          <th>Action</th>
        </tr>
      </thead>

      <tbody>
        ${absentRows}
      </tbody>
    </table>

  </div>

  <div class="footer">
    <p>Automatically generated by the Student Attendance System</p>
  </div>

</body>
</html>
`;

// CSS
const css = `
