  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 40px;
  font-family: Arial, Helvetica, sans-serif;
  color: #1f2937;
  background: #ffffff;
}

.header {
  text-align: center;
  margin-bottom: 35px;
  padding-bottom: 20px;
  border-bottom: 2px solid #e5e7eb;
}

.header h1 {
  margin: 0 0 8px;
  font-size: 30px;
  font-weight: 700;
  color: #111827;
}

.header p {
  margin: 0;
  font-size: 14px;
  color: #6b7280;
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 15px;
  margin-bottom: 35px;
}

.card {
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  padding: 20px;
  text-align: center;
  background: #f9fafb;
}

.card .label {
  display: block;
  font-size: 13px;
  color: #6b7280;
  margin-bottom: 8px;
}

.card .value {
  display: block;
  font-size: 28px;
  font-weight: 700;
  color: #111827;
}

.card.present {
  border-left: 5px solid #16a34a;
}

.card.absent {
  border-left: 5px solid #dc2626;
}

.card.warning {
  border-left: 5px solid #f59e0b;
}

.card.dismissal {
  border-left: 5px solid #7f1d1d;
}

.section {
  margin-top: 30px;
}

.section h2 {
  margin-bottom: 15px;
  font-size: 20px;
  color: #111827;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

thead {
  background: #f3f4f6;
}

th {
  padding: 12px;
  text-align: left;
  border-bottom: 2px solid #d1d5db;
  font-weight: 700;
}

td {
  padding: 12px;
  border-bottom: 1px solid #e5e7eb;
}

