  page-break-inside: avoid;
}

.no-data {
  text-align: center;
  padding: 25px;
  color: #16a34a;
  font-weight: 600;
}

.footer {
  margin-top: 40px;
  padding-top: 15px;
  border-top: 1px solid #e5e7eb;
  text-align: center;
  color: #9ca3af;
  font-size: 11px;
}

@media print {
  body {
    padding: 25px;
  }

  .summary-grid {
    page-break-inside: avoid;
  }

  .section {
    page-break-inside: auto;
  }
}
`;

return [
  {
    json: {
      html,
      css,
      report,
      fileName: `Daily_Attendance_Report_${date}.pdf`
    }
  }
];
